  | { kind: 'error'; error: string };

export function decode({ payload }: { payload: string }): User {
  const value: unknown = JSON.parse(payload);
  return UserSchema.parse(value);
}

export function newest({ xs }: { xs: Session[] }): Session | undefined {
  return xs.at(0);
}

export function sum({ xs }: { xs: number[] }): number {
  return xs.reduce((a, b) => a + b, 0);
}

